//! Actions-only original SDK/SQL/RPC sender capability, not SO/device execution.
#[path="im_send_option_protocol_tests.rs"]
mod options;
#[path="im_send_hardening_tests.rs"]
mod hardening;
use super::*;
use n::{im_inbox::{ImSendAction,ImSendMessage,PreparedImSend,ImSendPermit},im_send_policy::NativeImSendConfig};
fn policy()->NativeImSendConfig{NativeImSendConfig{send_text:true,send_info:true,auth_country_code:None}}
fn action(f:&Fixture,nonce:&str,recipient:&[u8],body:&str)->PreparedImSend{ImSendAction::original(f.temp.database.clone(),f.run.clone(),f.gate.clone(),f.backend.captured_im_binding().unwrap(),f.backend.captured_send_identity().unwrap(),recipient,ImSendMessage::text(body).unwrap(),nonce,Instant::now()+Duration::from_secs(30),&policy()).unwrap()}
fn fresh(f:&Fixture)->Arc<ImSendAction>{let PreparedImSend::Fresh(a)=action(f,&"a".repeat(32),b"1_2","original outbound text")else{panic!("fresh explicit native IM intent")};a}
fn state(f:&Fixture)->(i64,Option<i32>,Option<i64>){f.temp.database.with_conn(|c|c.query_row("SELECT state,request_id,message_index FROM app_voice_im_outbox",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"fixture")).unwrap()}
fn write(f:&mut Fixture,p:&Arc<ImSendPermit>)->n::arc_protocol::OwnedCallPackets{f.backend.prepare_im_send(p.clone(),Instant::now()+Duration::from_secs(30)).unwrap()}
fn result(f:&mut Fixture,id:i32,yes:bool,code:u32)->n::rpc_im_send::OwnedImSendReply{let mut w=Writer::new();if code>>16==1{w.u16(1).unwrap();w.u16(1).unwrap();}else{w.boolean(yes).unwrap();w.i64(i64::MAX).unwrap();w.i64(-1).unwrap();w.bytes(b"").unwrap();}let rpc=encode_reply(id,code,w.finish().expose_to_transport()).unwrap();let mut p=vec![1];p.extend_from_slice(rpc.expose_to_transport());assert!(f.backend.on_plaintext_packet(&f.owner,&f.scope,&p,1).unwrap().is_empty());let mut replies=f.backend.take_im_send_replies();assert_eq!(replies.len(),1);replies.pop().unwrap()}
#[test]fn im_send_policy_import_is_strict_and_never_borrows_received_or_user_read_permission(){for v in [r#"{}"#,r#"{"send_text":false,"send_info":false}"#,r#"{"send_text":true,"send_info":true,"uid":"forged"}"#]{assert!(serde_json::from_str::<NativeImSendConfig>(v).is_err()||serde_json::from_str::<NativeImSendConfig>(v).unwrap().validate().is_err());}let f=Fixture::new(true);let config=f.temp.database.with_conn(|c|account_store::load(c,f.run.line_id())).unwrap().unwrap();assert!(config.config.profile.im_send.is_none());assert!(config.config.profile.im_receipts.is_none()&&config.config.profile.im_user_read.is_none());}
#[test]fn im_send_unknown_intent_precedes_rpc_id_and_original_box_body_account_stats_are_exact(){let mut f=Fixture::new(true);let a=fresh(&f);assert_eq!(state(&f),(0,None,None));let p=a.permit(&policy()).unwrap();let packet=write(&mut f,&p);assert_eq!(packet.call_id,2);let request=decode_request(&packet.packets[0].expose_to_transport()[1..]).unwrap();assert_eq!(request.method,b"userSend.Message.Message");assert_eq!(request.metadata.len(),2);assert_eq!(request.metadata.iter().find(|p|p.key==b"id").unwrap().value,b"#Group");assert_eq!(request.metadata.iter().find(|p|p.key==b"token").unwrap().value,b"fixture-auth");let mut args=Reader::versioned(request.arguments).unwrap();assert_eq!(args.bytes().unwrap(),b"P2P/1_2");assert_eq!(args.bytes().unwrap(),b"Text");assert_eq!(args.bytes().unwrap(),br#"{"text":"original outbound text"}"#);assert!(args.properties().unwrap().is_empty());let params=args.properties().unwrap();assert_eq!(params.iter().find(|p|p.key==b"account").unwrap().value,b"[username:fixture@fixture.invalid]");assert_ne!(params.iter().find(|p|p.key==b"account").unwrap().value,b"fixture-user");assert_ne!(params.iter().find(|p|p.key==b"account").unwrap().value,b"[username:fixture-user@fixture.invalid]");let notify=args.properties().unwrap();assert_eq!(notify.iter().find(|p|p.key==b"Statistics.CountryCode").unwrap().value,b"");assert!(!notify.iter().any(|p|p.key==b"Notify.CountryCode"));args.finish().unwrap();assert_eq!(state(&f),(0,Some(packet.call_id),None));}
#[test]fn im_send_group_id_is_original_org_destination_not_a_user_udmr_or_sms_route(){let mut f=Fixture::new(true);let PreparedImSend::Fresh(a)=action(&f,&"a".repeat(32),b"1-2","group text")else{panic!()};let p=a.permit(&policy()).unwrap();let packet=write(&mut f,&p);let r=decode_request(&packet.packets[0].expose_to_transport()[1..]).unwrap();let mut args=Reader::versioned(r.arguments).unwrap();assert_eq!(args.bytes().unwrap(),b"Org/1-2");assert_eq!(f.count(),0);let count:i64=f.temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_user_reads",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(count,0);p.cancel();assert!(f.scope.is_open());}
#[test]fn im_send_same_nonce_unknown_is_metadata_replay_no_new_request_or_alias_query(){let f=Fixture::new(true);let _a=fresh(&f);let PreparedImSend::Replay(v)=action(&f,&"a".repeat(32),b"1_2","original outbound text")else{panic!("history only")};assert_eq!(v.state,"uncertain");assert_eq!(state(&f),(0,None,None));}
#[test]fn im_send_changed_body_or_recipient_same_nonce_conflicts_before_new_rpc(){let f=Fixture::new(true);let _a=fresh(&f);for(recipient,body)in[(b"1_2".as_slice(),"changed"),(b"9_9","original outbound text")]{assert_eq!(ImSendAction::original(f.temp.database.clone(),f.run.clone(),f.gate.clone(),f.backend.captured_im_binding().unwrap(),f.backend.captured_send_identity().unwrap(),recipient,ImSendMessage::text(body).unwrap(),&"a".repeat(32),Instant::now()+Duration::from_secs(1),&policy()).err(),Some("app_account_im_send_nonce_conflict"));}assert_eq!(state(&f),(0,None,None));}
#[test]fn im_send_original_unknown_blocks_any_new_nonce_or_alias_lookup_for_same_account_identity(){let f=Fixture::new(true);let _a=fresh(&f);assert_eq!(ImSendAction::original(f.temp.database.clone(),f.run.clone(),f.gate.clone(),f.backend.captured_im_binding().unwrap(),f.backend.captured_send_identity().unwrap(),b"[phone:+12345@fixture.invalid]",ImSendMessage::text("other body").unwrap(),&"b".repeat(32),Instant::now()+Duration::from_secs(1),&policy()).err(),Some("app_account_im_send_uncertain"));assert_eq!(state(&f),(0,None,None));}
#[test]fn im_send_queued_intent_drop_is_known_no_io_not_sdk_close_or_remote_ack(){let f=Fixture::new(true);let a=fresh(&f);a.cancel();assert_eq!(state(&f),(3,None,None));assert!(f.scope.is_open());}
#[test]fn im_send_queued_permit_cancel_records_not_sent_and_cannot_begin_or_close_scope(){let mut f=Fixture::new(true);let a=fresh(&f);let p=a.permit(&policy()).unwrap();let packet=write(&mut f,&p);p.cancel();assert_eq!(state(&f),(3,Some(packet.call_id),None));assert!(!p.begin_write(packet.call_id));assert!(!p.closed_original_io());assert!(f.scope.is_open());}
#[test]fn im_send_possible_or_full_write_cancel_keeps_unknown_and_closes_same_original_scope(){for full in [false,true]{let mut f=Fixture::new(true);let a=fresh(&f);let p=a.permit(&policy()).unwrap();let packet=write(&mut f,&p);assert!(p.begin_write(packet.call_id));if full{assert!(p.submitted());}p.cancel();assert_eq!(state(&f),(0,Some(packet.call_id),None));assert!(p.closed_original_io());assert!(!f.scope.is_open());}}
#[test]fn im_send_only_matched_original_private_result_sets_full_signed64_id_time_and_no_inbox_or_user_grant(){let mut f=Fixture::new(true);let a=fresh(&f);let p=a.permit(&policy()).unwrap();let packet=write(&mut f,&p);assert!(p.begin_write(packet.call_id));assert!(p.submitted());let reply=result(&mut f,packet.call_id,true,0);let view=p.resolve(&reply).unwrap();assert_eq!(view.state,"confirmed");assert_eq!(view.message_index.as_deref(),Some("9223372036854775807"));assert_eq!(view.original_time.as_deref(),Some("-1"));assert_eq!(state(&f),(1,Some(packet.call_id),Some(i64::MAX)));assert_eq!(f.count(),0);assert!(f.temp.database.get_recent_app_events(Some(f.run.line_id()),16).unwrap().is_empty());assert!(p.resolve(&reply).is_err());p.cancel();assert!(f.scope.is_open());}
#[test]fn im_send_native_false_and_version_rejection_are_known_negative_not_automatic_resend(){for code in [0,65537]{let mut f=Fixture::new(true);let a=fresh(&f);let p=a.permit(&policy()).unwrap();let packet=write(&mut f,&p);assert!(p.begin_write(packet.call_id));assert!(p.submitted());let r=result(&mut f,packet.call_id,false,code);let view=p.resolve(&r).unwrap();assert_eq!(view.state,"rejected");assert!(f.backend.prepare_im_send(p,Instant::now()+Duration::from_secs(1)).is_err());assert!(f.scope.is_open());}}
#[test]fn im_send_foreign_binding_or_scope_cannot_use_current_sender_identity_or_arm_original_id(){let mut f=Fixture::new(true);let other=Fixture::new(true);let a=fresh(&f);let p=a.permit(&policy()).unwrap();let mut backend=other.backend;assert!(backend.prepare_im_send(p.clone(),Instant::now()+Duration::from_secs(1)).is_err());assert_eq!(state(&f),(0,None,None));let packet=write(&mut f,&p);assert_eq!(packet.call_id,2);p.cancel();}
#[test]fn im_send_marker_sql_failure_cannot_allocate_send_id_or_create_a_second_capability(){let mut f=Fixture::new(true);f.temp.database.with_conn(|c|c.execute_batch("CREATE TRIGGER reject_send BEFORE INSERT ON app_voice_im_outbox BEGIN SELECT RAISE(ABORT,'fixture'); END").map_err(|_|"fixture")).unwrap();assert!(ImSendAction::original(f.temp.database.clone(),f.run.clone(),f.gate.clone(),f.backend.captured_im_binding().unwrap(),f.backend.captured_send_identity().unwrap(),b"1_2",ImSendMessage::text("body").unwrap(),&"a".repeat(32),Instant::now()+Duration::from_secs(1),&policy()).is_err());let query=f.backend.prepare_im_read(Arc::new(n::rpc_im::ImQuery::refresh(&[],-1).unwrap()),f.gate.clone(),Instant::now()+Duration::from_secs(1)).unwrap();assert_eq!(query.call_id,2);}
#[test]fn im_send_changed_marker_after_full_submission_keeps_unknown_not_accepted_from_boolean(){let mut f=Fixture::new(true);let a=fresh(&f);let p=a.permit(&policy()).unwrap();let packet=write(&mut f,&p);assert!(p.begin_write(packet.call_id));assert!(p.submitted());let r=result(&mut f,packet.call_id,true,0);f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_im_outbox SET arguments_hash=zeroblob(32)",[]).map_err(|_|"fixture")).unwrap();assert!(p.resolve(&r).is_err());assert_eq!(state(&f),(0,Some(packet.call_id),None));p.cancel();assert!(!f.scope.is_open());}
#[test]fn im_send_alias_span_or_uid_data_is_not_a_private_lookup_result_and_permit_is_not_reconstructed(){let f=Fixture::new(true);let PreparedImSend::Fresh(a)=action(&f,&"a".repeat(32),b"[phone:+12345@fixture.invalid]","body")else{panic!()};assert!(a.recipient_action().is_some());assert_eq!(a.permit(&policy()).err(),Some("app_account_im_send_recipient_unconfirmed"));assert_eq!(state(&f),(0,None,None));a.cancel();assert_eq!(state(&f),(3,None,None));}
#[test]fn im_send_debug_and_history_do_not_export_recipient_sdk_uri_token_or_body(){let f=Fixture::new(true);let a=fresh(&f);let p=a.permit(&policy()).unwrap();let debug=format!("{a:?} {p:?}");for secret in ["fixture","1_2","token","outbound","username"]{assert!(!debug.contains(secret));}let rows=f.temp.database.with_conn(|c|n::im_inbox::im_send_history(c,f.run.line_id(),16)).unwrap();let public=serde_json::to_string(&rows).unwrap();for secret in ["fixture","1_2","token","outbound","intent_hash","box_id","scope_epoch","user_nonce"]{assert!(!public.contains(secret));}}
